            if pointer_return_bits < 0 or pointer_return_bits > 64:
                raise ValueError(
                    "continuation pointer return contract is invalid"
                )
            if pointer_return_bits:
                function["pointer_return_bits"] = pointer_return_bits
            else:
                function.pop("pointer_return_bits", None)
