                            if not typed_exception_capability:
                                raise ValueError(
                                    "continuation typed exception "
                                    "capability is missing"
                                )
                            try:
                                type_id = int(str(raw_type_id), 10)
                            except (
                                TypeError, ValueError, OverflowError
                            ) as exc:
                                raise ValueError(
                                    "conditional exception type is invalid"
                                ) from exc
                            if type_id < 1 or type_id > (1 << 32) - 1:
                                raise ValueError(
                                    "conditional exception type is invalid"
                                )
