                            if not isinstance(token_operand, dict):
                                return False
                            if set(token_operand) == {"var"}:
                                variable = token_operand["var"]
                                return (
                                    isinstance(variable, str)
                                    and bool(variable)
                                    and len(variable) <= 256
                                )
                            if set(token_operand) != {"const", "bits"}:
                                return False
                            constant = token_operand["const"]
                            bits = token_operand["bits"]
                            return (
                                not isinstance(constant, bool)
                                and isinstance(constant, int)
                                and not isinstance(bits, bool)
                                and isinstance(bits, int)
                                and bits == raw_bits
                            )

